 ctx.beginPath();ctx.moveTo(-5,-8);ctx.quadraticCurveTo(-14,-22,-7,-25);ctx.moveTo(5,-9);ctx.quadraticCurveTo(14,-22,9,-26);ctx.stroke();
 ctx.fillStyle=m.col||'#8063cf';ctx.beginPath();ctx.ellipse(0,4,13,12,0,0,Math.PI*2);ctx.fill();
