 ctx.fillStyle='#182441';ctx.beginPath();ctx.arc(-6,-1,1.3,0,Math.PI*2);ctx.arc(0,-5,1.1,0,Math.PI*2);ctx.arc(6,-1,1.3,0,Math.PI*2);ctx.fill();
 ctx.shadowBlur=0;ctx.fillStyle='#d7c7ff';ctx.beginPath();ctx.ellipse(0,5,3,1.4,0,0,Math.PI*2);ctx.fill();
 // tiny alien feet and luminous back plates
