 ctx.shadowBlur=0;ctx.strokeStyle=boss.glow;ctx.globalAlpha=.55;ctx.lineWidth=2;
 ctx.beginPath();ctx.ellipse(0,height*.15,width*.37,height*.32,Math.sin(t*.8),t*.3,t*.3+Math.PI*1.65);ctx.stroke();
