function firePlayer(){if(mode!=='boss'||!boss)return;let target=boss;if(!target)return;let bl=BLASTERS.find(x=>x.id===equippedBlaster)||BLASTERS[0],a=Math.atan2(target.y-player.y,target.x-player.x);player.aim=a;let speed=510;pShots.push({x:player.x+Math.cos(a)*24,y:player.y+Math.sin(a)*24,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,r:bl.id==='ultra'?10:bl.id==='blast'?8:6,damage:bl.damage+characterBonus().damage,col:bl.color});burst(player.x+Math.cos(a)*24,player.y+Math.sin(a)*24,bl.color,5)}
function petAttack(dt){const pet=activePet();if(!pet||mode!=='boss'||!boss){petShotClock=0;return}petShotClock-=dt;if(petShotClock>0)return;const ox=player.x-29+Math.sin(t*2)*5,oy=player.y+25+Math.cos(t*2)*4;let a=Math.atan2(boss.y-oy,boss.x-ox),speed=430;pShots.push({x:ox+Math.cos(a)*18,y:oy+Math.sin(a)*18,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,r:5+pet.damage/40,damage:pet.damage,col:pet.color,petShot:true});petShotClock=pet.id==='legendary'?.48:pet.id==='epic'?.65:pet.id==='rare'?.85:1.05}
