function rollWithLuck(items){let weights=items.map(x=>x.weight),luck=luckUntil>Date.now()?1.25:1,total=weights.reduce((a,b)=>a+b,0),boosted=weights.map((w,i)=>w*(i===0?luck:1));let sum=boosted.reduce((a,b)=>a+b,0),r=Math.random()*sum;for(let i=0;i<items.length;i++){r-=boosted[i];if(r<=0)return items[i]}return items[items.length-1]}
