function artUrl(key){return ART_URLS[key]||ART_URLS.moon_muncher;}
function characterArtKey(choice){return ({'🌱':'moon_muncher','🐻':'bear','🦅':'eagle','🐯':'tiger','🦁':'lion','🦄':'unicorn','🐼':'red_panda','🦉':'owl','🐬':'dolphin','🐧':'penguin','🐉':'dragon','🦊':'fox','🐈\u200d⬛':'panther'}[choice]||'moon_muncher');}
function characterDisplayName(choice){return ({'🌱':'Moon Muncher','🐻':'Bear','🦅':'Eagle','🐯':'Tiger','🦁':'Lion','🦄':'Unicorn','🐼':'Red Panda','🦉':'Owl','🐬':'Dolphin','🐧':'Penguin','🐉':'Dragon','🦊':'Fox','🐈\u200d⬛':'Black Panther'}[choice]||'Moon Muncher');}
const CHARACTER_UPGRADES=[{value:'🌱',cost:0,hp:0,damage:0},{value:'🐻',cost:100,hp:15,damage:5},{value:'🦅',cost:180,hp:20,damage:8},{value:'🐯',cost:300,hp:30,damage:12},{value:'🦁',cost:450,hp:40,damage:16},{value:'🦄',cost:650,hp:50,damage:20},{value:'🐼',cost:850,hp:60,damage:24},{value:'🦉',cost:1100,hp:70,damage:28},{value:'🐬',cost:1400,hp:80,damage:32},{value:'🐧',cost:1750,hp:90,damage:36},{value:'🐉',cost:2200,hp:110,damage:45},{value:'🦊',cost:2800,hp:130,damage:55},{value:'🐈\u200d⬛',cost:5000,hp:200,damage:100}];
function characterUpgrade(choice){return CHARACTER_UPGRADES.find(c=>c.value===choice)||CHARACTER_UPGRADES[0]}
function characterPrice(choice){const c=characterUpgrade(choice);return c.cost?Math.round(c.cost*(1+Math.max(0,characterPurchases-1)*.25)):0}
function buyOrSelectCharacter(choice){if(ownedCharacters.includes(choice)){characterChoice=choice;saveEverything();return true}const c=characterUpgrade(choice),price=characterPrice(choice);if(coins<price){setText('shopStatus','You need '+price+' coins to unlock '+characterDisplayName(choice)+'.');return false}coins-=price;ownedCharacters.push(choice);characterPurchases++;characterChoice=choice;saveEverything();saveCoins();return true}
function characterBonus(choice=characterChoice){return characterUpgrade(choice)}
function petArtKey(id){return ({common:'comet_pup',rare:'nebula_fox',epic:'crystal_dragon',legendary:'solar_phoenix'}[id]||'comet_pup');}
function blasterArtKey(id){return ({starter:'blaster_starter',light:'blaster_light',blast:'blaster_blast',ultra:'blaster_ultra'}[id]||'blaster_starter');}
function redrawArtPreview(){if(!player||running)return;drawBackground(0);for(const a of moonMunches)drawMunch(a);if(boss&&mode==='boss')drawBoss();drawPlayer();if(activePet()){const pet=activePet();drawPet(pet,player.x-30,player.y+26);}if(hitboxesEnabled)drawHitboxes();}
